package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"               // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.Zero   // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0                   // PIC 99 len=2 = 0
var WsCount int64 = 0                    // PIC 99 len=2 = 0
var WsFEd string                         // PIC ZZ9.9 len=5
var WsCEd string                         // PIC -ZZ9.99 len=7

var TcRec TempRec

var tempLines []string
var tempIdx int

func parsePic9V9(s string, scale int) decimal.Decimal {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	dig := b.String()
	if dig == "" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(dig, 10, 64)
	if err != nil {
		d, _ := decimal.NewFromString(dig)
		return d.Shift(int32(-scale))
	}
	return decimal.New(n, int32(-scale))
}

func fitDecimal(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if d.IsZero() {
		return decimal.Zero
	}
	neg := d.Sign() < 0
	s := d.Abs().StringFixed(int32(scale))
	parts := strings.SplitN(s, ".", 2)
	intPart := parts[0]
	fracPart := ""
	if len(parts) > 1 {
		fracPart = parts[1]
	}
	if len(fracPart) < scale {
		fracPart += strings.Repeat("0", scale-len(fracPart))
	} else if len(fracPart) > scale {
		fracPart = fracPart[:scale]
	}
	combined := intPart + fracPart
	totalDigits := intDigits + scale
	if len(combined) > totalDigits {
		combined = combined[len(combined)-totalDigits:]
	} else if len(combined) < totalDigits {
		combined = strings.Repeat("0", totalDigits-len(combined)) + combined
	}
	newIntPart := combined[:intDigits]
	newFracPart := combined[intDigits:]
	var newStr string
	if scale > 0 {
		newStr = newIntPart + "." + newFracPart
	} else {
		newStr = newIntPart
	}
	res, _ := decimal.NewFromString(newStr)
	if neg && !res.IsZero() {
		res = res.Neg()
	}
	return res
}

func formatEdited(val decimal.Decimal, intDigits int, fracDigits int, hasSign bool) string {
	signChar := byte(' ')
	neg := val.Sign() < 0
	abs := val.Abs()
	if hasSign {
		if neg {
			signChar = '-'
		} else {
			signChar = ' '
		}
		if val.IsZero() {
			signChar = ' '
			abs = decimal.Zero
		}
	} else {
		if neg {
			abs = val.Abs()
		}
		if val.IsZero() {
			abs = decimal.Zero
		}
	}
	s := abs.StringFixed(int32(fracDigits))
	parts := strings.SplitN(s, ".", 2)
	intPart := parts[0]
	fracPart := ""
	if len(parts) > 1 {
		fracPart = parts[1]
	}
	if len(fracPart) < fracDigits {
		fracPart += strings.Repeat("0", fracDigits-len(fracPart))
	} else if len(fracPart) > fracDigits {
		fracPart = fracPart[:fracDigits]
	}
	combined := intPart + fracPart
	totalDigits := intDigits + fracDigits
	if len(combined) > totalDigits {
		combined = combined[len(combined)-totalDigits:]
	} else if len(combined) < totalDigits {
		combined = strings.Repeat("0", totalDigits-len(combined)) + combined
	}
	newIntPart := combined[:intDigits]
	newFracPart := combined[intDigits:]

	var intFormatted strings.Builder
	suppressed := true
	for i := 0; i < intDigits; i++ {
		d := newIntPart[i]
		isZ := i < intDigits-1
		if suppressed && d == '0' && isZ {
			intFormatted.WriteByte(' ')
		} else {
			intFormatted.WriteByte(d)
			suppressed = false
		}
	}
	edited := intFormatted.String() + "." + newFracPart
	if hasSign {
		edited = string(signChar) + edited
	}
	return edited
}

func formatPic99(v int64) string {
	mod := int64(100)
	vm := v % mod
	if vm < 0 {
		vm += mod
	}
	return fmt.Sprintf("%02d", vm)
}

// Paragraphs

func ReadPara() {
	if tempIdx >= len(tempLines) {
		WsEofFlag = "Y"
		return
	}
	line := tempLines[tempIdx]
	tempIdx++
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	fStr := line[4:8]
	TcRec.TcSensor = sensor
	TcRec.TcF = parsePic9V9(fStr, 1)
}

func ProcessPara() {
	diff := TcRec.TcF.Sub(decimal.NewFromInt(32))
	prod := diff.Mul(decimal.NewFromInt(5))
	quot := prod.Div(decimal.NewFromInt(9))
	rounded := quot.Round(2)
	WsC = fitDecimal(rounded, 3, 2)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatEdited(TcRec.TcF, 3, 1, false)
	WsCEd = formatEdited(WsC, 3, 2, true)
	line := TcRec.TcSensor + " " + WsFEd + "F " + WsCEd + "C"
	fmt.Fprintln(os.Stdout, line)
	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			tempLines = []string{}
		} else {
			fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
			os.Exit(1)
		}
	} else {
		defer f.Close()
		scanner := bufio.NewScanner(f)
		// allow larger lines if needed
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			tempLines = append(tempLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
			os.Exit(1)
		}
	}
	tempIdx = 0
	WsEofFlag = "N"
	WsC = decimal.Zero
	WsFreeze = 0
	WsCount = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	countStr := formatPic99(WsCount)
	freezeStr := formatPic99(WsFreeze)
	fmt.Fprintf(os.Stdout, "READINGS: %s BELOW ZERO: %s\n", countStr, freezeStr)
}

func main() {
	MainPara()
}
